// PopulateEventMetadata stores pending event metadata (W3C SCXML 5.10).
// Note: event name is set separately via setCurrentEvent(); metadata supplies
// only the name the event ARRIVED under, when that is not its value's own.
func (p *StaticRecordCallPolicy) PopulateEventMetadata(meta *sce.EventMetadata) {
	// NL→IR Item C1 Path A: lift the dequeued event's typed payload from the
	// type-erased carrier into the typed policy field the native guards read
	// (twin of the C11 pop loop's `sm->pending_payload = evt.payload`).
	p.pendingPayloadTag = StaticRecordCallPayloadTagNone
	switch v := meta.TypedPayload.(type) {
	case StaticRecordCallLedgerEntryPayload:
		p.pendingPayloadTag = StaticRecordCallPayloadTagLedgerEntry
		p.pendingLedgerEntryPayload = v
	}

	p.pendingEventData = meta.Data
}

// LiftTypedPayload binds the dequeued event's typed `_event.data` view from
// the data it carries (NL→IR Item C1 Path A).
//
// The typed carrier PopulateEventMetadata reads is filled by one producer, the
// generated Raise<Event> inject seam. Every other producer — <send> with
// <param>, an invoke forwarding either way, autoforward, BasicHTTP, mesh —
// fills EventMetadata.Data, so the schema's fields are read out of that here.
// A refusal is returned for the engine to raise as error.execution, which is
// what W3C SCXML 3.13 gives for a guard that cannot be evaluated.
func (p *StaticRecordCallPolicy) LiftTypedPayload(event StaticRecordCallEvent, meta *sce.EventMetadata) error {
	// A typed carrier already bound the view, so the producer was the
	// inject seam and there is nothing to read out of `Data`.
	if p.pendingPayloadTag != StaticRecordCallPayloadTagNone {
		return nil
	}
	switch event {
	case StaticRecordCallEventLedgerEntry:
		fields, err := sce.LiftPayload(meta.Data)
		if err != nil {
			return err
		}
		var payload StaticRecordCallLedgerEntryPayload
		if payload.id, err = sce.PayloadUnsigned[uint32](fields, "id"); err != nil {
			return err
		}
		if payload.amount, err = sce.PayloadSigned[int32](fields, "amount"); err != nil {
			return err
		}
		p.pendingLedgerEntryPayload = payload
		p.pendingPayloadTag = StaticRecordCallPayloadTagLedgerEntry
	}
	return nil

}

// ClearEventMetadata resets pending event metadata (W3C SCXML 5.10).
func (p *StaticRecordCallPolicy) ClearEventMetadata() {
	// NL→IR Item C1 Path A: reset the typed-payload tag (PopulateEventMetadata
	// always re-establishes it for the next event; this keeps a stale payload
	// from being read between macrosteps).
	p.pendingPayloadTag = StaticRecordCallPayloadTagNone

	p.pendingEventData = ""
}



